import React, { useState } from 'react'
import { RadioButton } from 'primereact/radiobutton';
        

export default function Dynamic() {
    const [value, setValue] = useState('');
    const categories = [
        {
            key: 'accounting',
            name: 'Accounting'
        },
        {
            key: 'finance',
            name: 'Finance'
        },
        {
            key: 'marketing',
            name: 'Marketing'
        },
        {
            key: 'sales',
            name: 'Sales'
        },
    ]
        return (
            <div className="fxb fcol wrap gp4">
                {categories.map((category) => {
                    return (
                        <div key={category.key} className="fxb fvc">
                            <RadioButton inputId={category.key} name="category" value={category.name} onChange={(e) => setValue(e.value)} checked={value === category.name} />
                            <label className="mgl2" htmlFor={category.key}>{category.name}</label>
                        </div>
                    );
                })}
            </div>
        );
}
